import numpy as np
W0 = W_copy()

def outcome(obs):
    c12x=obs[:,234]; c12y=obs[:,235]; bx=obs[:,26]; by=obs[:,27]
    blue = (np.abs(c12x-bx)<0.427)&(np.abs(c12y-by)<0.602)
    red = (c12x>0.96)&(c12x<2.284)&(c12y>0.132)&(c12y<0.672)
    tb = np.argmax(blue) if blue.any() else 10**9
    tr = np.argmax(red) if red.any() else 10**9
    if tb<tr: return "SUCCESS", int(tb)
    if tr<tb: return "RED", int(tr)
    return "NONE", int(obs.shape[0])

def run_pi(pi, n=256, iters=10):
    A = [1]*n
    obs = None
    for it in range(iters):
        obs,_ = observe(params=W0, actions=A, n_steps=n)
        T = obs.shape[0]
        Anew = [pi(obs[t]) for t in range(T)]
        if Anew == A[:T]:
            return outcome(obs), True
        A = Anew
    return outcome(obs), False

